Attractions is the only service with a break in its uptime series, and its pods are the only ones with missing samples. Every other pod's uptime runs continuously across the incident. The evidence is sufficient to write up.

<br>

```json
{
  "root_causes": [
    {
      "service": "attractions",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_k8s_pod_name, count(*) n, min(value) v0, max(value) v1 FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'attractions%' GROUP BY 1,2",
          "claim": "Attractions pod attractions-6485cb64bc-tgtxc restart counter climbed from 1 to 6 during the incident, versus 0 in normal."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, metric, count(*) n, avg(value) avgv FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND attr_k8s_deployment_name LIKE 'attractions%' GROUP BY 1,2 UNION ALL SELECT 'norm', metric, count(*), avg(value) FROM normal_metrics WHERE metric='k8s.deployment.available' AND attr_k8s_deployment_name LIKE 'attractions%' GROUP BY 1,2",
          "claim": "Attractions deployment availability fell from about 18 pods to about 2 of 17 desired during the incident."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, count(*) n FROM abnormal_traces WHERE service_name='attractions' UNION ALL SELECT 'norm', count(*) FROM normal_traces WHERE service_name='attractions'",
          "claim": "Attractions emitted no spans during the abnormal window, while it emitted about 1100 spans in normal."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "attractions",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code sc, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' AND span_name IN ('HTTP /cinema','HTTP /restaurants','HTTP /museums') GROUP BY 1,2,3",
          "claim": "Frontend /cinema, /restaurants and /museums return HTTP 500 errors in about 126 of 129 requests during the incident."
        }
      ]
    }
  ]
}
```

